insert into public.pt_words (id, deck_id, word, pos, ru, ex, exru, note, level, tema, sort, uk, exuk, noteuk, en, exen, noteen) values
('w:ser','a1','ser','глаг.','быть (постоянный признак)','O João é professor numa escola de Lisboa.','Жуан — учитель в лиссабонской школе.','Постоянное свойство; временное состояние — estar','A1','A1',0,'бути (постійна ознака)','Жуан — учитель у лісабонській школі.','Постійна властивість; тимчасовий стан — estar','to be (permanent quality)','João is a teacher at a school in Lisbon.','Permanent quality; a temporary state takes estar'),
('w:estar','a1','estar','глаг.','быть, находиться (временно)','Hoje estou muito cansado, trabalhei o dia todo.','Сегодня я очень устал, работал весь день.','Временное состояние и местонахождение','A1','A1',1,'бути, перебувати (тимчасово)','Сьогодні я дуже втомився, працював цілий день.','Тимчасовий стан і місцеперебування','to be (temporary state, place)','I am very tired today, I worked all day.','Temporary state and whereabouts'),
('w:ter','a1','ter','глаг.','иметь, быть должным','Tenho dois irmãos e uma irmã mais nova.','У меня два брата и младшая сестра.','ter de + инфинитив = быть должным','A1','A1',2,'мати; мусити','У мене два брати і молодша сестра.','ter de + інфінітив = мусити','to have; to have to','I have two brothers and a younger sister.','ter de + infinitive = to have to'),
('w:haver','a1','haver','глаг.','иметься, быть в наличии','Há um supermercado aqui perto?','Здесь рядом есть супермаркет?','Безлично только «há», без мн. ч.','A1','A1',3,'бути в наявності, матися','Тут поблизу є супермаркет?','Безособово лише «há», без множини','there to be, to exist','Is there a supermarket near here?','Impersonal há only, no plural form'),
('w:viver','a1','viver','глаг.','жить, быть живым','Vivo em Portugal desde o ano passado.','Я живу в Португалии с прошлого года.','Где именно живёшь — morar em','A1','A1',4,'жити, бути живим','Я живу в Португалії з минулого року.','Де саме живеш — morar em','to live, to be alive','I have lived in Portugal since last year.','Where exactly you live — morar em'),
('w:sem','a1','sem','предл.','без','Bebo o café sem açúcar, por favor.','Я пью кофе без сахара, пожалуйста.','Противоположно com','A1','A1',5,'без','Я п’ю каву без цукру, будь ласка.','Протилежне до com','without','I drink my coffee without sugar, please.','Opposite of com'),
('w:conhecer','a1','conhecer','глаг.','знать (быть знакомым), познакомиться','Conheço bem esta zona da cidade.','Я хорошо знаю этот район города.','Знакомство; знание фактов — saber','A1','A8',6,'знати (бути знайомим), познайомитися','Я добре знаю цей район міста.','Знайомство; знання фактів — saber','to know (be acquainted), to meet','I know this part of the city well.','Acquaintance; knowing facts is saber'),
('w:dizer','a1','dizer','глаг.','говорить, сказать','O que é que disseste? Não ouvi bem.','Что ты сказал? Я не расслышал.','Неправильный: digo, disse, dito','A1','A8',7,'говорити, сказати','Що ти сказав? Я не розчув.','Неправильне: digo, disse, dito','to say, to tell','What did you say? I did not catch it.','Irregular: digo, disse, dito'),
('w:escrever','a1','escrever','глаг.','писать','Escrevi um email ao senhorio esta manhã.','Я написал письмо хозяину квартиры сегодня утром.','Причастие неправильное: escrito','A1','A8',8,'писати','Я написав листа господарю квартири сьогодні вранці.','Дієприкметник неправильний: escrito','to write','I wrote an email to the landlord this morning.','Irregular participle: escrito'),
('w:esperar','a1','esperar','глаг.','ждать; надеяться','Espero pelo autocarro há vinte minutos.','Я жду автобус уже двадцать минут.','esperar por alguém — ждать кого-то','A1','A8',9,'чекати; сподіватися','Я чекаю на автобус уже двадцять хвилин.','esperar por alguém — чекати на когось','to wait; to hope','I have been waiting for the bus for twenty minutes.','esperar por alguém — to wait for someone'),
('w:falar','a1','falar','глаг.','говорить, разговаривать','Falo um pouco de português, mas ainda erro muito.','Я немного говорю по-португальски, но пока много ошибаюсь.','falar com alguém, falar de algo','A1','A8',10,'говорити, розмовляти','Я трохи говорю португальською, але поки багато помиляюся.','falar com alguém, falar de algo','to speak, to talk','I speak a little Portuguese, but I still make mistakes.','falar com alguém, falar de algo'),
('w:pensar','a1','pensar','глаг.','думать','Penso que ela tem razão neste assunto.','Я думаю, что она права в этом вопросе.','pensar em — думать о чём-то','A1','A8',11,'думати','Я думаю, що вона має рацію в цьому питанні.','pensar em — думати про щось','to think','I think she is right about this.','pensar em — to think about something'),
('w:perguntar','a1','perguntar','глаг.','спрашивать','Vou perguntar ao empregado onde fica a saída.','Спрошу у официанта, где выход.','perguntar a alguém — спросить у кого-то','A1','A8',12,'запитувати','Запитаю в офіціанта, де вихід.','perguntar a alguém — запитати в когось','to ask a question','I will ask the waiter where the exit is.','perguntar a alguém — to ask someone'),
('w:pergunta','a1','a pergunta','сущ.','вопрос','Posso fazer-lhe uma pergunta rápida?','Можно задать вам быстрый вопрос?','fazer uma pergunta — задать вопрос','A1','A8',13,'запитання','Можна поставити вам швидке запитання?','fazer uma pergunta — поставити запитання','question','May I ask you a quick question?','fazer uma pergunta — to ask a question'),
('w:responder','a1','responder','глаг.','отвечать','Ela ainda não respondeu à minha mensagem.','Она ещё не ответила на моё сообщение.','responder a — отвечать на','A1','A8',14,'відповідати','Вона ще не відповіла на моє повідомлення.','responder a — відповідати на','to answer, to reply','She has not answered my message yet.','responder a — to reply to'),
('w:resposta','a1','a resposta','сущ.','ответ','A resposta dele foi curta e clara.','Его ответ был коротким и ясным.','ж. р.','A1','A8',15,'відповідь','Його відповідь була короткою і ясною.','ж. р.','answer, reply','His answer was short and clear.','feminine'),
('w:dar','a1','dar','глаг.','давать','Dá-me o teu número de telefone, por favor.','Дай мне свой номер телефона, пожалуйста.','Неправильный: dou, dás, dá, damos, dão','A1','A9',16,'давати','Дай мені свій номер телефону, будь ласка.','Неправильне: dou, dás, dá, damos, dão','to give','Give me your phone number, please.','Irregular: dou, dás, dá, damos, dão'),
('w:então','a1','então','нареч.','тогда, итак, ну и','Então, o que é que fazemos amanhã?','Ну и что мы будем делать завтра?','Очень частое разговорное слово-связка','A1','A9',17,'тоді, отже, ну і','Ну і що ми робитимемо завтра?','Дуже часте розмовне слово-зв’язка','so, then, well','So, what shall we do tomorrow?','Very common spoken connector'),
('w:mas','a1','mas','союз','но','Gosto de peixe, mas hoje prefiro carne.','Я люблю рыбу, но сегодня предпочитаю мясо.','','A1','A9',18,'але','Я люблю рибу, але сьогодні віддаю перевагу м’ясу.','','but','I like fish, but today I would rather have meat.',''),
('w:porque','a1','porque','союз','потому что','Cheguei tarde porque perdi o comboio.','Я пришёл поздно, потому что опоздал на поезд.','Слитно — ответ; porquê — в вопросе на конце','A1','A9',19,'тому що','Я прийшов пізно, бо запізнився на потяг.','Разом — відповідь; porquê — у питанні на кінці','because','I was late because I missed the train.','One word for the answer; porquê ends a question'),
('w:porquê','a1','porquê','нареч.','почему (в конце вопроса)','Não vens connosco? Porquê?','Ты не пойдёшь с нами? Почему?','В начале вопроса — por que razão / porque','A1','A9',20,'чому (у кінці питання)','Ти не підеш з нами? Чому?','На початку питання — por que razão / porque','why (at the end of a question)','Are you not coming with us? Why?','At the start of a question — por que razão or porque'),
('w:sobre','a1','sobre','предл.','о, про; над','Falámos sobre o trabalho durante o almoço.','Мы говорили о работе за обедом.','«о теме» — sobre, реже acerca de','A1','A9',21,'про; над','Ми говорили про роботу за обідом.','«Про тему» — sobre, рідше acerca de','about; over','We talked about work over lunch.','About a topic — sobre, more rarely acerca de'),
('w:almoçar','a1','almoçar','глаг.','обедать','Almoço quase sempre no refeitório da empresa.','Я почти всегда обедаю в столовой на работе.','','A1','B3',22,'обідати','Я майже завжди обідаю в їдальні на роботі.','','to have lunch','I almost always have lunch in the company canteen.',''),
('w:almoço','a1','o almoço','сущ.','обед','O almoço é servido a partir do meio-dia.','Обед подают с полудня.','м. р.','A1','B3',23,'обід','Обід подають з полудня.','ч. р.','lunch','Lunch is served from midday.','masculine'),
('w:pequeno-almoço','a1','o pequeno-almoço','сущ.','завтрак','Ao pequeno-almoço como pão com queijo.','На завтрак я ем хлеб с сыром.','м. р.; пишется через дефис, мн. ч.: pequenos-almoços','A1','B3',24,'сніданок','На сніданок я їм хліб із сиром.','ч. р.; пишеться через дефіс, мн.: pequenos-almoços','breakfast','For breakfast I eat bread with cheese.','masc.; hyphenated, plural pequenos-almoços'),
('w:tomar o pequeno-almoço','a1','tomar o pequeno-almoço','выраж.','завтракать','Tomo o pequeno-almoço às sete e meia.','Я завтракаю в половине восьмого.','Говорят и comer o pequeno-almoço','A1','B8',25,'снідати','Я снідаю о пів на восьму.','Кажуть і comer o pequeno-almoço','to have breakfast','I have breakfast at half past seven.','comer o pequeno-almoço is also said'),
('w:jantar','a1','jantar','глаг.','ужинать','Hoje jantamos fora, num restaurante do bairro.','Сегодня мы ужинаем вне дома, в ресторане по соседству.','Существительное o jantar — ужин','A1','B3',26,'вечеряти','Сьогодні ми вечеряємо не вдома, у ресторані по сусідству.','Іменник o jantar — вечеря','to have dinner','Tonight we are eating out, at a restaurant nearby.','The noun o jantar means dinner'),
('w:lanchar','a1','lanchar','глаг.','перекусить, полдничать','As crianças lancham depois da escola.','Дети перекусывают после школы.','','A1','B3',27,'перекусити, підвечіркувати','Діти перекусують після школи.','','to have a snack','The children have a snack after school.',''),
('w:lanche','a1','o lanche','сущ.','перекус, полдник','Levo sempre um lanche na mochila.','Я всегда беру перекус в рюкзаке.','м. р.','A1','B3',28,'перекус, підвечірок','Я завжди беру перекус у рюкзаку.','ч. р.','snack, afternoon snack','I always take a snack in my backpack.','masculine'),
('w:caderno','a1','o caderno','сущ.','тетрадь','Escrevi os verbos novos no caderno.','Я записал новые глаголы в тетрадь.','м. р.','A1','B3',29,'зошит','Я записав нові дієслова в зошит.','ч. р.','notebook','I wrote the new verbs in my notebook.','masculine'),
('w:caneta','a1','a caneta','сущ.','ручка','Emprestas-me uma caneta azul?','Одолжишь мне синюю ручку?','ж. р.','A1','B3',30,'ручка','Позичиш мені синю ручку?','ж. р.','pen','Will you lend me a blue pen?','feminine'),
('w:lápis','a1','o lápis','сущ.','карандаш','Prefiro escrever a lápis para poder apagar.','Я предпочитаю писать карандашом, чтобы можно было стереть.','Мн. ч. не меняется: os lápis','A1','B3',31,'олівець','Я волію писати олівцем, щоб можна було стерти.','Множина не змінюється: os lápis','pencil','I prefer to write in pencil so I can rub it out.','Plural unchanged: os lápis'),
('w:livro','a1','o livro','сущ.','книга','Estou a ler um livro em português muito simples.','Я читаю очень простую книгу на португальском.','м. р., несмотря на «книга»','A1','B3',32,'книжка','Я читаю дуже просту книжку португальською.','ч. р., попри «книжка»','book','I am reading a very simple book in Portuguese.','masculine'),
('w:quadro','a1','o quadro','сущ.','доска (в классе); картина','A professora escreveu a data no quadro.','Учительница написала дату на доске.','м. р.','A1','B3',33,'дошка (у класі); картина','Учителька написала дату на дошці.','ч. р.','board (in class); painting','The teacher wrote the date on the board.','masculine'),
('w:sala de aula','a1','a sala de aula','сущ.','класс, аудитория','A sala de aula fica no primeiro andar.','Класс находится на втором этаже.','1.º andar в Португалии = 2-й этаж','A1','B3',34,'клас, аудиторія','Клас розташований на другому поверсі.','1.º andar у Португалії = 2-й поверх','classroom','The classroom is one floor up.','In Portugal 1.º andar is one flight above the ground floor'),
('w:turma','a1','a turma','сущ.','класс, группа (учащихся)','Na minha turma há alunos de cinco países.','В моей группе учатся ребята из пяти стран.','ж. р.; о людях, не о помещении','A1','B3',35,'клас, група (учнів)','У моїй групі вчаться студенти з п’яти країн.','ж. р.; про людей, не про приміщення','class, group of students','In my class there are students from five countries.','fem.; about the people, not the room'),
('w:colega','a1','o colega','сущ.','коллега, одноклассник','Vou almoçar com um colega do trabalho.','Я иду обедать с коллегой по работе.','Форма одна: o colega / a colega','A1','B3',36,'колега, однокласник','Я йду обідати з колегою по роботі.','Форма одна: o colega / a colega','colleague, classmate','I am going to lunch with a colleague from work.','One form: o colega and a colega'),
('w:disciplina','a1','a disciplina','сущ.','учебный предмет; дисциплина','A minha disciplina preferida é história.','Мой любимый предмет — история.','ж. р.','A1','B3',37,'навчальний предмет; дисципліна','Мій улюблений предмет — історія.','ж. р.','school subject; discipline','My favourite subject is history.','feminine'),
('w:curso','a1','o curso','сущ.','курс, обучение','Fiz um curso de português de três meses.','Я прошёл трёхмесячный курс португальского.','м. р.','A1','B3',38,'курс, навчання','Я пройшов тримісячний курс португальської.','ч. р.','course, programme of study','I did a three-month Portuguese course.','masculine'),
('w:semestre','a1','o semestre','сущ.','семестр','O segundo semestre começa em fevereiro.','Второй семестр начинается в феврале.','м. р.','A1','B3',39,'семестр','Другий семестр починається в лютому.','ч. р.','semester','The second semester starts in February.','masculine'),
('w:recreio','a1','o recreio','сущ.','перемена (в школе)','Os alunos jogam à bola no recreio.','Ученики играют в мяч на перемене.','м. р.','A1','B3',40,'перерва (у школі)','Учні грають у м’яч на перерві.','ч. р.','break, playtime at school','The pupils play ball at break.','masculine'),
('w:sair da escola','a1','sair da escola','выраж.','уходить из школы (после уроков)','Saio da escola às três e meia da tarde.','Я ухожу из школы в половине четвёртого.','sair de + место','A1','B3',41,'виходити зі школи (після уроків)','Я виходжу зі школи о пів на четверту.','sair de + місце','to leave school after lessons','I leave school at half past three.','sair de + a place'),
('w:começar a trabalhar','a1','começar a trabalhar','выраж.','начинать работать','Começo a trabalhar às nove da manhã.','Я начинаю работать в девять утра.','começar a + инфинитив','A1','B3',42,'починати працювати','Я починаю працювати о дев’ятій ранку.','começar a + інфінітив','to start work','I start work at nine in the morning.','começar a + infinitive'),
('w:sair do trabalho','a1','sair do trabalho','выраж.','уходить с работы','Saio do trabalho por volta das seis.','Я ухожу с работы около шести.','','A1','B3',43,'іти з роботи','Я йду з роботи близько шостої.','','to leave work','I leave work at about six.',''),
('w:horário de trabalho','a1','o horário de trabalho','сущ.','рабочий график','O meu horário de trabalho é das nove às cinco.','Мой рабочий график — с девяти до пяти.','м. р.','A1','B3',44,'робочий графік','Мій робочий графік — з дев’ятої до п’ятої.','ч. р.','working hours','My working hours are nine to five.','masculine'),
('w:chegar a casa','a1','chegar a casa','выраж.','приходить домой','Chego a casa cansado, mas ainda cozinho.','Я прихожу домой уставшим, но всё равно готовлю.','Без артикля: a casa, не «à casa»','A1','B3',45,'приходити додому','Я приходжу додому втомлений, але все одно готую.','Без артикля: a casa, не «à casa»','to get home','I get home tired, but I still cook.','No article: a casa, never à casa'),
('w:lavar-se','a1','lavar-se','глаг.','мыться, умываться','Lavo-me e visto-me em dez minutos.','Я умываюсь и одеваюсь за десять минут.','Возвратный: lavo-me, lavas-te','A1','B3',46,'митися, вмиватися','Я вмиваюся й одягаюся за десять хвилин.','Зворотне: lavo-me, lavas-te','to wash, to have a wash','I wash and get dressed in ten minutes.','Reflexive: lavo-me, lavas-te'),
('w:vestir-se','a1','vestir-se','глаг.','одеваться','Veste-se sempre de preto no inverno.','Зимой он всегда одевается в чёрное.','e → i: visto-me, vestes-te','A1','B3',47,'одягатися','Узимку він завжди одягається в чорне.','e → i: visto-me, vestes-te','to get dressed','In winter he always dresses in black.','e turns to i: visto-me, vestes-te'),
('w:despir-se','a1','despir-se','глаг.','раздеваться','Despe-se e deita-se logo a seguir ao jantar.','Он раздевается и ложится сразу после ужина.','Противоположно vestir-se','A1','B3',48,'роздягатися','Він роздягається і лягає одразу після вечері.','Протилежне до vestir-se','to undress','He undresses and goes to bed right after dinner.','Opposite of vestir-se'),
